package main

import (
	"bytes"
	"net/http"
	_ "net/http/pprof" // 暴露 /debug/pprof/heap
	"runtime"
	"sync"
)

// per-P 池化：bytes.Buffer 是典型短命对象，频繁 new 会打到 mcache 但增加 GC 标记量
var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

func encode(s string) []byte {
	b := bufPool.Get().(*bytes.Buffer)
	b.Reset() // 关键：Get 出来的可能带旧数据
	defer bufPool.Put(b)
	b.WriteString(s)
	// 必须复制再返回，否则 Put 后底层数组被复用，调用方拿到的 slice 会被改写
	out := make([]byte, b.Len())
	copy(out, b.Bytes())
	return out
}

func dumpGC() {
	var m runtime.MemStats
	runtime.ReadMemStats(&m)
	// NumGC: 累计 GC 次数；PauseNs 是最近 256 次停顿的环形缓冲
	// HeapAlloc: 当前堆活跃字节；NextGC: 下次触发的 goal
	_ = m
}

func main() {
	// GODEBUG=gctrace=1 go run main.go 可看每次 GC 一行汇总
	// go tool pprof http://localhost:6060/debug/pprof/heap 看 inuse/alloc
	go http.ListenAndServe(":6060", nil)
	select {}
}
